components.css:
.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-sample :is(a,button,summary,[tabindex]):focus-visible { outline: 2px solid var(--docs-accent, #c83214); outline-offset: 2px; }
.ds-docs-icon-button { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; flex-shrink: 0; border: 1px solid transparent; border-radius: 2px; background: transparent; color: var(--docs-ink, #141413); cursor: pointer; }
.ds-docs-icon-button:hover { background: var(--docs-ground, #f2efe9); border-color: var(--docs-rule, #dfdbd2); color: var(--docs-accent, #c83214); }
@media (max-width:760px) { .ds-docs-icon-button { width: 38px; height: 38px; margin-top: 6px; } }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; }
.ds-docs-sample :is(a,button,summary,[tabindex]):focus-visible { outline: 2px solid var(--docs-accent, #c83214); outline-offset: 2px; }
.ds-docs-sample input:focus-visible { outline: 2px solid var(--docs-accent, #c83214); outline-offset: -1px; border-color: var(--docs-accent, #c83214); }
.ds-docs-masthead { height: 54px; display: flex; align-items: center; gap: 18px; padding: 0 24px 0 0; background: var(--docs-paper, #faf8f4); border-bottom: 1px solid var(--docs-ink-rule, #141413); font-family: "Aileron", "Docs Public Sans", sans-serif; }
.ds-docs-wordmark { width: 236px; height: 100%; flex-shrink: 0; display: flex; align-items: center; gap: 5px; padding: 0 24px; border-right: 1px solid var(--docs-rule, #dfdbd2); color: var(--docs-ink, #141413); font-size: 16px; font-weight: 700; letter-spacing: -0.025em; text-decoration: none; white-space: nowrap; }
.ds-docs-wordmark span { color: var(--docs-muted, #59564f); font-weight: 400; }
.ds-docs-tabs { display: flex; align-self: stretch; gap: 26px; padding-left: 18px; font-size: 13.5px; font-weight: 600; }
.ds-docs-tabs a { position: relative; display: flex; align-items: center; color: var(--docs-muted, #59564f); text-decoration: none; }
.ds-docs-tabs a:hover, .ds-docs-tabs a[aria-current] { color: var(--docs-ink, #141413); }
.ds-docs-tabs a[aria-current]::after { content: ""; height: 2px; background: var(--docs-accent, #c83214); position: absolute; bottom: -1px; left: 0; right: 0; }
.ds-docs-header-search { margin-left: auto; height: 100%; display: flex; align-items: center; padding-left: 18px; border-left: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-header-search input { width: 256px; height: 32px; border: 1px solid var(--docs-strong-rule, #b8b2a6); background: var(--docs-input, #ffffff); border-radius: 2px; padding: 0 11px; font-size: 13px; color: var(--docs-ink, #141413); caret-color: var(--docs-accent, #c83214); }
.ds-docs-header-search input::placeholder { color: var(--docs-muted, #59564f); opacity: 1; }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-search-label { display: block; font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 13px; font-weight: 700; margin-bottom: 8px; }
.ds-docs-content-search { width: 100%; height: 42px; border: 1px solid var(--docs-strong-rule, #b8b2a6); border-radius: 2px; background: var(--docs-input, #ffffff); padding: 0 13px; font: 400 15px/1.62 "Docs Public Sans", "Aileron", sans-serif; color: var(--docs-ink, #141413); caret-color: var(--docs-accent, #c83214); }
.ds-docs-content-search::placeholder { color: var(--docs-muted, #59564f); opacity: 1; }
.ds-docs-content-search:focus-visible { outline: 2px solid var(--docs-accent, #c83214); outline-offset: -1px; border-color: var(--docs-accent, #c83214); }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-filter-strip { display: flex; flex-wrap: wrap; gap: 2px 18px; padding: 0; border-top: 1px solid var(--docs-rule, #dfdbd2); border-bottom: 1px solid var(--docs-ink-rule, #141413); }
.ds-docs-filter-chip { position: relative; padding: 5px 0 6px; border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; background: transparent; color: var(--docs-muted, #59564f); font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 12.5px; font-weight: 600; cursor: pointer; }
.ds-docs-filter-chip:hover { color: var(--docs-ink, #141413); }
.ds-docs-filter-chip[aria-pressed="true"] { color: var(--docs-ink, #141413); border-bottom-color: var(--docs-accent, #c83214); }
.ds-docs-filter-chip:focus-visible { outline: 2px solid var(--docs-accent, #c83214); outline-offset: 2px; }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; }
.ds-docs-directory { width: 236px; background: var(--docs-ground, #f2efe9); padding: 20px 18px 28px 24px; font-size: 13.5px; line-height: 1.38; border-right: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-directory section { padding-bottom: 14px; margin-bottom: 14px; border-bottom: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-directory section:last-child { border-bottom: 0; margin-bottom: 0; padding-bottom: 0; }
.ds-docs-directory h2 { font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--docs-muted, #59564f); margin: 0 0 6px; }
.ds-docs-directory a { display: block; padding: 4px 10px; margin-left: -10px; border-left: 1px solid transparent; color: var(--docs-ink, #141413); text-decoration: none; }
.ds-docs-directory a:hover { color: var(--docs-accent, #c83214); }
.ds-docs-directory a[aria-current] { background: var(--docs-selected, #faf8f4); color: var(--docs-selection-ink, #c83214); border-left-color: var(--docs-accent, #c83214); font-weight: 600; }
.ds-docs-directory a:focus-visible { outline: 2px solid var(--docs-accent, #c83214); outline-offset: 2px; }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; }
.ds-docs-margin { width: 224px; padding: 24px 24px 28px; font-size: 12.5px; border-left: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-margin h2 { font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--docs-muted, #59564f); font-weight: 700; margin: 0 0 10px; }
.ds-docs-contents-links { border-left: 1px solid var(--docs-rule, #dfdbd2); padding: 0 0 0 13px; display: flex; flex-direction: column; gap: 8px; }
.ds-docs-contents-links a { color: var(--docs-muted, #59564f); line-height: 1.42; margin-left: -14px; padding-left: 13px; border-left: 1px solid transparent; text-decoration: none; }
.ds-docs-contents-links a:hover { color: var(--docs-ink, #141413); }
.ds-docs-contents-links a[aria-current] { color: var(--docs-accent, #c83214); border-left-color: var(--docs-accent, #c83214); font-weight: 600; }
.ds-docs-contents-nested { padding-left: 23px !important; }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-table-scroll { max-width: 100%; overflow-x: auto; }
.ds-docs-command-table { width: 100%; border-collapse: collapse; border-top: 1px solid var(--docs-ink-rule, #141413); text-align: left; font-size: 13.5px; font-variant-numeric: tabular-nums; }
.ds-docs-command-table th { font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--docs-muted, #59564f); padding: 7px 14px 7px 0; border-bottom: 1px solid var(--docs-strong-rule, #b8b2a6); }
.ds-docs-command-table th:first-child { width: 170px; }
.ds-docs-command-table th:nth-child(2) { width: 130px; }
.ds-docs-command-table td { padding: 7.5px 14px 7.5px 0; border-bottom: 1px solid var(--docs-rule, #dfdbd2); vertical-align: baseline; line-height: 1.45; }
.ds-docs-command-table :is(th,td):last-child { padding-right: 0; }
.ds-docs-command-table td:first-child { font-weight: 600; white-space: nowrap; }
.ds-docs-command-table td:first-child code { display: inline-block; padding: 1px 6px; background: var(--docs-ground, #f2efe9); border: 1px solid var(--docs-rule, #dfdbd2); border-radius: 2px; color: var(--docs-ink, #141413); font: 600 12.5px/1.45 ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace; }
.ds-docs-command-table td:first-child a { text-decoration: none; }
.ds-docs-command-table td:first-child a:hover code { border-color: var(--docs-accent, #c83214); color: var(--docs-accent, #c83214); }
.ds-docs-command-table td:nth-child(2) a { color: var(--docs-ink, #141413); font-weight: 600; text-decoration: none; }
.ds-docs-command-table td:nth-child(2) a:hover { color: var(--docs-accent, #c83214); }
.ds-docs-command-table td:last-child { color: var(--docs-muted, #59564f); }
.ds-docs-command-owner { display: none; }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-code-inline { display: flex; align-items: stretch; border: 1px solid var(--docs-strong-rule, #b8b2a6); background: var(--docs-ground, #f2efe9); max-width: 100%; }
.ds-docs-code-scroll { flex: 1; min-width: 0; overflow-x: auto; }
.ds-docs-code-block { margin: 0; padding: 10px 16px; background: transparent; color: var(--docs-ink, #141413); font: 12.5px/1.55 ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace; white-space: pre; }
.ds-docs-code-tools { flex-shrink: 0; display: flex; align-items: center; padding: 0 8px; border-left: 1px solid var(--docs-rule, #dfdbd2); background: var(--docs-ground, #f2efe9); color: var(--docs-muted, #59564f); font-size: 11.5px; }
.ds-docs-copy-button { display: inline-flex; align-items: center; gap: 5px; padding: 2px 6px; background: transparent; border: 1px solid transparent; border-radius: 2px; font: 500 11.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; color: var(--docs-muted, #59564f); cursor: pointer; }
.ds-docs-copy-button:hover { color: var(--docs-accent, #c83214); background: var(--docs-paper, #faf8f4); border-color: var(--docs-rule, #dfdbd2); }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-guide-strip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border-top: 1px solid var(--docs-ink-rule, #141413); border-bottom: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-guide-item { padding: 11px 16px 11px 0; border-right: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-guide-item:nth-child(n+2) { padding-left: 16px; }
.ds-docs-guide-item:last-child { border-right: 0; padding-right: 0; }
.ds-docs-guide-item a { font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 14px; font-weight: 700; color: var(--docs-ink, #141413); text-decoration: none; }
.ds-docs-guide-item a:hover { color: var(--docs-accent, #c83214); }
.ds-docs-guide-item p { font-size: 12.5px; line-height: 1.42; color: var(--docs-muted, #59564f); margin: 3px 0 0; }

.ds-docs-sample { background: var(--docs-paper, #faf8f4); color: var(--docs-ink, #141413); font: 400 15.5px/1.62 "Docs Public Sans", "Aileron", sans-serif; padding: 8px; }
.ds-docs-search-results { padding: 0; margin: 0; list-style: none; border-top: 1px solid var(--docs-ink-rule, #141413); }
.ds-docs-search-results li { border-bottom: 1px solid var(--docs-rule, #dfdbd2); }
.ds-docs-search-results a { display: block; padding: 16px 0; text-decoration: none; }
.ds-docs-result-title { font-family: "Aileron", "Docs Public Sans", sans-serif; font-size: 17px; font-weight: 700; color: var(--docs-ink, #141413); }
.ds-docs-search-results a:hover .ds-docs-result-title { color: var(--docs-accent, #c83214); text-decoration: underline; text-underline-offset: 4px; }
.ds-docs-result-context { display: block; color: var(--docs-muted, #59564f); font-size: 12px; margin: 2px 0 6px; }
.ds-docs-result-description { display: block; color: var(--docs-ink, #141413); font-size: 14.5px; max-width: 68ch; }
